    "landingProblemTitleLine1": "Genel Fince çalışması",
    "landingProblemTitleLine2": "gerçek sonuçlar için yeterli değildir.",
    "landingProblemBody": "Genel dil uygulamaları Fince'yi soyut olarak öğretir. Floently hayatınızı değiştirecek şeyler için aslında ihtiyacınız olan Fince'yi öğretir: YKI'i geçmek, işe alınmak, vatandaş olmak.",
    "landingOutcomeWallTitle": "YKI bir duvardır, bitiş çizgisi değil",
    "landingOutcomeWallBody": "Çoğu öğrencinin genel dil derslerinden daha fazlasına ihtiyacı vardır. YKI sınavı için, iş için, günlük iletişim için ve vatandaşlığa ve daimi oturuma giden uzun tırmanış için Fince'ye ihtiyaçları var.",
    "landingOutcomeWorkplaceTitle": "İşyeri Fincesi farklı bir beceridir",
    "landingOutcomeWorkplaceBody": "Uluslararası çalışanların vardiyada daha güvenli iletişim, daha sorunsuz işe alım ve sürtüşme yerine şirkette kalmayı destekleyen dil güveni için pratik Fince'ye ihtiyacı var.",
    "landingOutcomeCitiesTitle": "Şehirler entegrasyon sonucunun sahibidir",
    "landingOutcomeCitiesBody": "Asistanların, öğrenmeyi yalnızca sınıf bitirme sertifikalarına değil, istihdam edilebilirliğe, katılıma ve Finlandiya toplumuna anlamlı katılıma bağlayan dil desteğine ihtiyaçları var.",
