    "landingPlatformYkiBody": "Konuşma, yazma, okuma, dinleme — iş, vatandaşlık ve daimi ikamet için YKI puanlama değerlendirme listeleriyle eşleşen geri bildirimli rehberli uygulama.",
    "landingPlatformProfessionalEyebrow": "Profesyonel Fince",
    "landingPlatformProfessionalTitle": "Doktorlar, hemşireler ve pratik hemşireler için.",
    "landingPlatformProfessionalBody": "Mesleğe özel senaryolar, kelime dağarcığı ve diyaloglar. Hasta devir teslimi, klinik dokümantasyon, günlük ekip çalışması; ders kitabı durumlarına değil, gerçek işe yönelik dil.",
    "landingPlatformLifeEyebrow": "Finlandiya'da Yaşam",
    "landingPlatformLifeTitle": "Günlük hizmetler, resmi iletişim.",
    "landingPlatformLifeBody": "KELA, Migri, sağlık hizmetleri, okullar, bankalar ve uzun vadeli vatandaşlık ve daimi ikamet hedefleri için ihtiyacınız olan Fince.",
    "landingInsideEyebrow": "İÇİNDE NELER VAR",
