    "landingInsideTitleLine2": "YKI, iş ve yerleşim.",
    "landingInsideBody": "Her öğrenci sınav hazırlığı, mesleki Fince ve günlük yaşam Fincesi arasında geçiş yapar. Floently onları sürekli bir yolda tutar.",
